const consulta = $('Unificar entrada').first().json.chatInput;
const salida = $input.first().json.output;
let p = null;
const bruto = typeof salida === 'string' ? salida : JSON.stringify(salida ?? {});
// Extrae el primer objeto JSON balanceado (tolera texto o llaves de mas antes o despues)
function primerObjeto(t) {
  const ini = t.indexOf('{');
  if (ini < 0) return null;
  let prof = 0, enCad = false, esc = false;
  for (let i = ini; i < t.length; i++) {
    const c = t[i];
    if (enCad) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') enCad = false; continue; }
    if (c === '"') enCad = true;
    else if (c === '{') prof++;
    else if (c === '}') { prof--; if (prof === 0) return t.slice(ini, i + 1); }
  }
  return null;
}
try { const o = primerObjeto(bruto); p = o ? JSON.parse(o) : null; } catch (e) { p = null; }

const VALIDAS = ['CONSULTA_BIBLIOTECA', 'PRECHEQUEO_TERCEROS', 'ESCALAR_A_LOGISTICA'];
const limpio = v => (v === undefined || v === null || String(v).trim() === '' || String(v).trim().toLowerCase() === 'null') ? null : String(v).trim();
const hoy = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);   // fecha de hoy en Argentina (UTC-3)

const modelo = limpio(p?.modelo);
const fecha = limpio(p?.fecha_trabajo);
let categoria = (p && VALIDAS.includes(p.categoria)) ? p.categoria : 'ESCALAR_A_LOGISTICA';
let motivoEscalamiento = null;

if (!p || !VALIDAS.includes(p.categoria)) {
  motivoEscalamiento = 'CLASIFICACION_DUDOSA';
} else if (categoria === 'ESCALAR_A_LOGISTICA') {
  motivoEscalamiento = 'FUERA_DE_ALCANCE_O_DUDOSA';
} else if (!modelo) {
  categoria = 'ESCALAR_A_LOGISTICA'; motivoEscalamiento = 'FALTA_MODELO';
} else if (categoria === 'PRECHEQUEO_TERCEROS') {
  const fechaOk = fecha && /^\d{4}-\d{2}-\d{2}$/.test(fecha) && !isNaN(Date.parse(fecha + 'T00:00:00Z'));
  if (!fechaOk) { categoria = 'ESCALAR_A_LOGISTICA'; motivoEscalamiento = 'FALTA_FECHA_VALIDA'; }
  else if (fecha < hoy) { categoria = 'ESCALAR_A_LOGISTICA'; motivoEscalamiento = 'FECHA_PASADA'; }
}

const cliente = (limpio(p?.cliente) || '').replace(/[^A-Za-z0-9ÁÉÍÓÚáéíóúÑñÜü .,&'-]/g, '').trim().slice(0, 80) || null;
return [{ json: {
  consulta, categoria, cliente,
  categoria_clasificada: p?.categoria ?? null,
  motivo_clasificador: limpio(p?.motivo),
  salida_cruda_clasificador: bruto.slice(0, 500),
  modelo, fecha_trabajo: fecha,
  localidad: limpio(p?.localidad), provincia: limpio(p?.provincia),
  motivo_escalamiento: motivoEscalamiento,
  trace: []
} }];

const base = $('Validar clasificación y datos mínimos').first().json;
const entrada = $('Preparar entrada W1 (consulta)').first().json;
const salida = $input.first().json;
return [{ json: { ...base, w1: salida,
  trace: [...base.trace, { worker: 'W1_consulta_biblioteca', recibio: entrada, devolvio: salida }] } }];

const ctx = $input.first().json;
const w1 = ctx.w1;
const L = [];
let estado;
const v = x => (x === null || x === undefined || x === '') ? 'sin dato' : x;
if (w1.status === 'success') {
  const d = w1.data;
  L.push('### Ficha del modelo ' + d.modelo);
  L.push('');
  L.push('- **Marca:** ' + v(d.marca));
  L.push('- **Categoría:** ' + v(d.categoria));
  L.push('- **Peso del bulto más pesado:** ' + (d.peso_bulto_mas_pesado_kg === null ? 'sin dato' : d.peso_bulto_mas_pesado_kg + ' kg') + ' _(es el del bulto más pesado, no el peso total)_');
  L.push('- **Cantidad de bultos:** ' + (d.cantidad_bultos === null ? v(d.cantidad_bultos_texto) : d.cantidad_bultos));
  L.push('- **Dimensiones:** ' + v(d.dimensiones));
  L.push('- **Apilable:** ' + v(d.apilable));
  L.push('- **Datos que faltan:** ' + v(d.datos_que_faltan));
  L.push('');
  if (d.datos_base_completos) { estado = 'RESUELTO - DATOS BASE COMPLETOS'; L.push('**Estado:** DATOS BASE COMPLETOS'); }
  else { estado = 'RESUELTO - REGISTRO INCOMPLETO'; L.push('Corresponde consultar con Logística.'); L.push(''); L.push('**Estado:** INCOMPLETO - derivar a Logística'); }
} else {
  const c = w1.error?.codigo;
  estado = 'ESCALADO A LOGISTICA - ' + c;
  L.push('### Consulta derivada a Logística');
  L.push('');
  L.push(c === 'MODELO_NO_ENCONTRADO' ? 'El modelo **' + ctx.modelo + '** no figura en la Biblioteca.' : 'No se pudo consultar la Biblioteca: ' + (w1.error?.mensaje || 'error desconocido') + '.');
  L.push('');
  L.push('Corresponde consultar con Logística.');
  L.push('');
  L.push('**Estado:** INCOMPLETO - derivar a Logística');
}
return [{ json: { respuesta: L.join('\n'), estado, consulta: ctx.consulta, categoria: ctx.categoria, modelo: ctx.modelo, trace: ctx.trace } }];

const base = $('Validar clasificación y datos mínimos').first().json;
const entrada = $('Preparar entrada W1 (peso)').first().json;
const salida = $input.first().json;
const peso = salida.status === 'success' ? (salida.data?.peso_bulto_mas_pesado_kg ?? null) : null;
return [{ json: { ...base, w1: salida, peso_kg: peso, peso_ok: peso !== null && peso > 0,
  trace: [...base.trace, { worker: 'W1_consulta_biblioteca', recibio: entrada, devolvio: salida }] } }];

const base = $('Fusionar contexto W1 (peso)').first().json;
const entrada = $('Preparar entrada W2').first().json;
const salida = $input.first().json;
const ok = salida.status === 'success';
return [{ json: { ...base, w2: salida, w2_ok: ok, necesita_tercero: ok && salida.data?.necesita_tercero === true,
  trace: [...base.trace, { worker: 'W2_prechequeo_terceros', recibio: entrada, devolvio: salida }] } }];

const base = $('Fusionar contexto W2').first().json;
const entrada = $('Preparar entrada W3').first().json;
const salida = $input.first().json;
return [{ json: { ...base, w3: salida,
  trace: [...base.trace, { worker: 'W3_terceros_cercanos', recibio: entrada, devolvio: salida }] } }];

const ctx = $input.first().json;
const L = [];
let estado;
const v = x => (x === null || x === undefined || x === '') ? null : x;
const MOTIVOS = { PESO_EXCEDE_FLOTA: 'el bulto más pesado supera la fuerza de todos los vehículos propios', FLOTA_OCUPADA: 'los vehículos propios que pueden levantar ese bulto están ocupados en esa fecha' };

function candidato(c) {
  const cap = { SI: 'alcanza según las notas', NO: 'no alcanzaría según las notas', A_CONFIRMAR: 'a confirmar con el proveedor' }[c.alcanza_segun_notas];
  const zona = c.cercania === 'MISMA_LOCALIDAD' ? 'misma localidad' : 'misma provincia';
  const f = ['- **' + (c.nombre || '(sin nombre cargado)') + '** - ' + (c.localidad || 'localidad sin dato') + ' _(' + zona + ')_'];
  f.push('  - Capacidad: ' + cap);
  if (v(c.domicilio)) f.push('  - Domicilio: ' + c.domicilio);
  if (v(c.telefono)) f.push('  - Teléfono: ' + c.telefono);
  if (v(c.contacto)) f.push('  - Contacto: ' + c.contacto);
  if (v(c.mail)) f.push('  - Mail: ' + c.mail);
  if (v(c.notas)) f.push('  - Notas: ' + c.notas);
  if (c.valor_referencia) f.push('  - _' + c.valor_referencia + '_');
  return f.join('\n');
}

if (!ctx.w2_ok) {
  estado = 'ESCALADO A LOGISTICA - ' + (ctx.w2.error?.codigo || 'W2');
  L.push('### Consulta derivada a Logística');
  L.push('');
  L.push('No se pudo hacer el prechequeo de terceros: ' + (ctx.w2.error?.mensaje || 'error desconocido') + '.');
  L.push('No se asume que no haga falta tercero.');
  L.push('');
  L.push('Corresponde consultar con Logística.');
} else if (!ctx.necesita_tercero) {
  const d = ctx.w2.data;
  estado = 'RESUELTO - NO HACE FALTA TERCERO';
  L.push('### No haría falta tercero');
  L.push('');
  L.push('**Equipo:** ' + ctx.modelo + '  ·  **Fecha del trabajo:** ' + d.fecha_trabajo);
  L.push('');
  L.push('- **Peso del bulto más pesado:** ' + d.peso_kg + ' kg');
  L.push('- **Vehículos propios que pueden levantarlo:** ' + d.vehiculos_capaces.join(', '));
  L.push('- **Libres en esa fecha:** ' + d.vehiculos_capaces_libres.join(', '));
  L.push('- **Ventana revisada en el Calendar de flota:** ' + d.ventana_revisada.desde + ' al ' + d.ventana_revisada.hasta);
  L.push('');
  L.push('_Este prechequeo no reserva ningún vehículo. La asignación y la decisión final son de Logística._');
} else {
  const d = ctx.w2.data;
  L.push('### Hace falta tercero');
  L.push('');
  L.push('**Equipo:** ' + ctx.modelo + '  ·  **Fecha del trabajo:** ' + d.fecha_trabajo);
  L.push('');
  L.push('**Motivo:** ' + (MOTIVOS[d.motivo] || d.motivo) + '.');
  L.push('');
  L.push('- **Peso del bulto más pesado:** ' + d.peso_kg + ' kg');
  L.push('- **Fuerza máxima de la flota propia:** ' + d.fuerza_maxima_flota_kg + ' kg');
  if (d.motivo === 'FLOTA_OCUPADA') L.push('- **Ocupados en esa fecha:** ' + d.vehiculos_capaces_ocupados.join(', '));
  const w3 = ctx.w3;
  L.push('');
  if (w3 && w3.status === 'success') {
    const t = w3.data;
    estado = 'RESUELTO - TERCEROS SUGERIDOS';
    L.push('### Terceros cercanos a ' + (t.ubicacion_pedida.localidad || t.provincia_considerada || 'la zona pedida'));
    L.push('');
    L.push(t.total_encontrados.gruas + ' grúas y ' + t.total_encontrados.autoelevadores + ' autoelevadores encontrados. Se muestran hasta 5 de cada tipo.');
    if (t.gruas.length) { L.push(''); L.push('**Grúas**'); L.push(''); t.gruas.forEach(c => { L.push(candidato(c)); L.push(''); }); }
    if (t.autoelevadores.length) { L.push('**Autoelevadores**'); L.push(''); t.autoelevadores.forEach(c => { L.push(candidato(c)); L.push(''); }); }
    L.push('**Avisos**');
    L.push('');
    t.avisos.forEach(a => L.push('- ' + a));
    L.push('');
    L.push('Corresponde confirmar con Logística.');
  } else {
    estado = 'ESCALADO A LOGISTICA - ' + (w3?.error?.codigo || 'SIN_RESULTADO_W3');
    L.push('### Terceros cercanos');
    L.push('');
    L.push('No pude armar la lista de terceros cercanos: ' + (w3?.error?.mensaje || 'sin resultado') + '.');
    L.push('');
    L.push('Corresponde consultar con Logística.');
  }
}
L.push('');
L.push('**Estado:** ' + estado);
return [{ json: { respuesta: L.join('\n'), estado, consulta: ctx.consulta, categoria: ctx.categoria, modelo: ctx.modelo, trace: ctx.trace } }];

function previo(nombres) {
  for (const n of nombres) { try { return $(n).first().json; } catch (e) { /* ese nodo no se ejecuto */ } }
  return null;
}
const ctx = previo(['Fusionar contexto W2', 'Fusionar contexto W1 (peso)', 'Fusionar contexto W1 (consulta)', 'Validar clasificación y datos mínimos']) || {};
const entrada = $input.first().json;
const trace = [...(ctx.trace || [])];
let codigo, detalle;

if (entrada.error) {
  // Un Worker no respondio o fallo (incluye time-out): se escala, no se reintenta ni se supone un resultado
  const fallido = ['Preparar entrada W3', 'Preparar entrada W2', 'Preparar entrada W1 (peso)', 'Preparar entrada W1 (consulta)'];
  let nombre = 'Worker (ver la ejecución)', recibio = null;
  for (const n of fallido) { try { recibio = $(n).first().json; nombre = n.replace('Preparar entrada ', 'Worker '); break; } catch (e) { /* no se ejecuto */ } }
  const mensaje = String(entrada.error?.message || entrada.error || 'error desconocido');
  codigo = 'FALLO_TECNICO_DE_WORKER';
  detalle = nombre + ' no respondió o falló: ' + mensaje + '.';
  trace.push({ worker: nombre, recibio, devolvio: { status: 'error', error: { codigo, mensaje } } });
} else if (ctx.peso_ok === false) {
  const c = ctx.w1?.error?.codigo || 'SIN_PESO_EN_BIBLIOTECA';
  codigo = c;
  detalle = c === 'MODELO_NO_ENCONTRADO'
    ? 'El modelo "' + ctx.modelo + '" no figura en la Biblioteca.'
    : (c === 'ERROR_TECNICO' ? 'No se pudo consultar la Biblioteca: ' + (ctx.w1?.error?.mensaje || '') + '.'
      : 'El modelo figura en la Biblioteca pero sin peso del bulto más pesado, por eso no se puede comparar contra la flota. No se asume que no haga falta tercero.');
} else {
  codigo = ctx.motivo_escalamiento || 'SIN_CATEGORIA';
  const TXT = {
    CLASIFICACION_DUDOSA: 'No pude clasificar con seguridad lo que se pide.',
    FUERA_DE_ALCANCE_O_DUDOSA: 'El pedido está fuera de lo que resuelve este asistente (tarifas, presupuestos, rutas, accesos o elección de vehículo) o no quedó claro.',
    FALTA_MODELO: 'No se indicó el modelo del equipo.',
    FALTA_FECHA_VALIDA: 'Falta una fecha válida del trabajo (por ejemplo, 5 de diciembre).',
    FECHA_PASADA: 'La fecha indicada ya pasó.',
    SIN_CATEGORIA: 'No se pudo asignar una categoría.'
  };
  detalle = TXT[codigo] || 'Pedido dudoso.';
}
const L = ['### Consulta derivada a Logística', '', 'Esta consulta la tiene que ver una persona de Logística.', '', '**Motivo:** ' + detalle, '', 'Corresponde consultar con Logística.', '', '**Estado:** ESCALADO A LOGÍSTICA'];
return [{ json: { respuesta: L.join('\n'), estado: 'ESCALADO A LOGISTICA - ' + codigo, consulta: ctx.consulta, categoria: ctx.categoria || null, modelo: ctx.modelo || null, trace } }];

const j = $input.first().json;
const escalado = j.estado.startsWith('ESCALADO');
const corto = (o) => {
  if (!o) return 'sin respuesta';
  if (o.status === 'error') return 'error ' + (o.error?.codigo || '') + ': ' + (o.error?.mensaje || '');
  const d = o.data || {};
  if (o.worker === 'W1_consulta_biblioteca') return 'success - ' + d.modelo + ': peso ' + (d.peso_bulto_mas_pesado_kg ?? 'sin dato') + ' kg, bultos ' + (d.cantidad_bultos ?? 'sin dato');
  if (o.worker === 'W2_prechequeo_terceros') return 'success - necesita_tercero=' + d.necesita_tercero + ', motivo=' + (d.motivo || 'ninguno') + ', capaces=[' + (d.vehiculos_capaces || []).join(', ') + '], libres=[' + (d.vehiculos_capaces_libres || []).join(', ') + ']';
  if (o.worker === 'W3_terceros_cercanos') return 'success - gruas=' + d.total_encontrados.gruas + ', autoelevadores=' + d.total_encontrados.autoelevadores + ' (zona: ' + (d.ubicacion_pedida.localidad || d.provincia_considerada || '-') + ')';
  return 'success';
};
const trace = j.trace || [];
const workers = trace.length ? trace.map(t => t.worker.split('_')[0].replace('Worker ', 'W')).join(' -> ') : 'ninguno (resuelto o escalado sin invocar Workers)';
const detalle = trace.length ? trace.map(t => '• ' + t.worker + '\n   recibió: ' + JSON.stringify(t.recibio) + '\n   devolvió: ' + corto(t.devolvio)).join('\n') : '• (sin invocaciones)';
let mem = 'sin dato'; try { const x = $('Contexto de memoria').first().json; mem = x.es_nuevo ? 'chat nuevo (se creó el registro del caso)' : 'chat recurrente (memoria del caso recuperada)'; } catch (e) {}
const log = (escalado ? ':warning: *Manager - consulta ESCALADA a Logística*' : ':white_check_mark: *Manager - consulta procesada*') + ' (Sechi, Medical Rigging)\n'
  + '*Consulta recibida:* ' + j.consulta + '\n'
  + '*Categoría asignada:* ' + (j.categoria || 'sin categoría') + '\n'
  + '*Resultado:* ' + j.estado + '\n'
  + '*Workers invocados:* ' + workers + '\n'
  + '*Memoria:* ' + mem + '\n'
  + '*Detalle de cada Worker:*\n' + detalle;
return [{ json: { respuesta: j.respuesta, log_texto: log, estado: j.estado, categoria: j.categoria, modelo: j.modelo } }];

const c = $('Consolidar respuesta y log').first().json;
let ctx = null; try { ctx = $('Contexto de memoria').first().json; } catch (e) { ctx = null; }
let reg = null; try { reg = $('Preparar registro de memoria').first().json; } catch (e) { reg = null; }
const L = [];
if (ctx && !ctx.es_nuevo) {
  try {
    const p = JSON.parse(ctx.resumen_previo || 'null');
    if (p && p.asunto_principal) L.push('_Retomo el caso en curso de este chat. Última vez: ' + p.asunto_principal + '. Pendiente: ' + (p.accion_requerida || 'sin dato') + '._', '');
  } catch (e) { /* sin resumen previo */ }
}
L.push(c.respuesta);
if (ctx) {
  L.push('', '---', '**Memoria del caso** (Session_ID `' + String(ctx.sessionId).slice(0, 8) + '…`)', '');
  if (!ctx.record_id) {
    L.push('- No se pudo acceder a la memoria en esta consulta; se respondió sin ella.');
  } else {
    L.push('- Chat: ' + (ctx.es_nuevo ? 'nuevo, se creó el registro del caso.' : 'recurrente, se recuperó la memoria del caso.'));
    if (reg) {
      L.push('- Cliente del caso: ' + (reg.cliente || 'todavía no se nombró'));
      L.push('- Mensajes en esta sesión: ' + reg.mensajes);
      if (reg.estado_conservado) L.push('- Estado del caso: se conservó el anterior (esta consulta se escaló a Logística y no cambia el caso).');
      L.push('- Resumen automático: ' + (reg.resumen_actualizado ? 'actualizado (se activa al superar los 5 mensajes).'
        : (reg.resumen_invalido ? 'no se actualizó: la salida del modelo no pasó la validación y se conservó el resumen anterior.'
          : 'todavía no se activa (se activa al superar los 5 mensajes).')));
    }
  }
}
return [{ json: { output: L.join('\n') } }];

const r = $input.first().json;
const f = r.fields ?? r;
return [{ json: { es_nuevo: false, record_id: r.id,
  resumen_previo: f['Resumen Consolidado'] || '', estado_previo: f['Estado del Caso'] || '', datos_previos: f['Datos Clave'] || '' } }];

const limpio = (s, max) => String(s ?? '').replace(/\[(INICIO|FIN)[^\]]*\]/gi, '').replace(/#{2,}/g, '').replace(/\s+/g, ' ').trim().slice(0, max);
const t = $('Unificar entrada').first().json;
const mem = $input.first().json;
const sessionId = String(t.sessionId || '').replace(/[^A-Za-z0-9_-]/g, '');
let datos = {}; try { datos = mem.datos_previos ? JSON.parse(mem.datos_previos) : {}; } catch (e) { datos = {}; }
let resumen = null; try { resumen = mem.resumen_previo ? JSON.parse(mem.resumen_previo) : null; } catch (e) { resumen = null; }
const L = [];
if (!mem.es_nuevo) {
  if (datos.cliente) L.push('El cliente del caso en curso es ' + limpio(datos.cliente, 80) + '.');
  if (mem.estado_previo) L.push('Estado de su última solicitud: ' + limpio(mem.estado_previo, 60) + '.');
  if (resumen && resumen.asunto_principal) {
    const puntos = Array.isArray(resumen.puntos_clave) ? resumen.puntos_clave.map(x => limpio(x, 140)).join('; ') : '';
    L.push('El contexto de la última charla es: ' + limpio(resumen.asunto_principal, 160) + (puntos ? '. Puntos clave: ' + puntos : '') + (resumen.accion_requerida ? '. Acción pendiente: ' + limpio(resumen.accion_requerida, 200) : '') + '.');
  }
  const dk = [];
  if (datos.ultimo_modelo) dk.push('modelo ' + limpio(datos.ultimo_modelo, 60));
  if (datos.fecha_trabajo) dk.push('fecha del trabajo ' + limpio(datos.fecha_trabajo, 12));
  if (datos.localidad) dk.push('localidad ' + limpio(datos.localidad, 60));
  if (datos.provincia) dk.push('provincia ' + limpio(datos.provincia, 60));
  if (dk.length) L.push('Datos clave del último caso: ' + dk.join(', ') + '.');
}
if (L.length) L.unshift('El usuario es una persona de Logística de Sechi que viene trabajando un caso de cliente en este chat.');
const bloque = L.length
  ? ['[INICIO DE CONTEXTO COMPARTIDO]', '### CONFIGURACIÓN DE IDENTIDAD Y MEMORIA DE LARGO PLAZO ###', ...L, '### FIN DEL CONTEXTO COMPARTIDO ###', '[FIN DEL CONTEXTO COMPARTIDO]'].join('\n')
  : '';
return [{ json: { chatInput: t.chatInput, sessionId, es_nuevo: !!mem.es_nuevo, record_id: mem.record_id || null,
  resumen_previo: mem.resumen_previo || '', estado_previo: mem.estado_previo || '', datos_previos: datos,
  bloque_memoria: bloque, tiene_contexto: L.length > 0 } }];

const limpio = (s, max) => String(s ?? '').replace(/\[(INICIO|FIN)[^\]]*\]/gi, '').replace(/#{2,}/g, '').replace(/\s+/g, ' ').trim().slice(0, max);
const hist = $input.first().json;
const ctx = $('Contexto de memoria').first().json;
const fin = $('Consolidar respuesta y log').first().json;
const UMBRAL = 5;
const turnos = (Array.isArray(hist.messages) ? hist.messages : []).filter(g => g && g.human !== undefined);
const mensajes = turnos.length;
function msjCliente(t) { const s = String(t ?? ''); const i = s.indexOf('Mensaje de la persona:'); return limpio(i >= 0 ? s.slice(i + 22) : s, 300); }
function clasif(t) {
  const s = String(t ?? ''); const a = s.indexOf('{'); const z = s.lastIndexOf('}');
