    varios_pedidos: b.varios_pedidos === true, cantidad_pedidos: b.cantidad_pedidos || 1,
    correos_omitidos: b.correos_omitidos || []
  }
} }];

const m4 = $('Unificar entrada').first().json.m4;
const c = m4.campos;
function previo(nombres) {
  for (const n of nombres) { try { const j = $(n).first().json; if (j) return j; } catch (e) { /* ese nodo no se ejecutó */ } }
  return null;
}
const fin = previo(['Armar escalamiento', 'Armar respuesta (prechequeo)', 'Armar respuesta (consulta)']) || {};
const estadoManager = String(fin.estado || '');
const trace = Array.isArray(fin.trace) ? fin.trace : [];
const dato = w => { const t = trace.find(x => String(x.worker || '').startsWith(w)); return (t && t.devolvio && t.devolvio.status === 'success') ? t.devolvio.data : null; };
const w1 = dato('W1'), w2 = dato('W2'), w3 = dato('W3');

// Resultado del Manager: solo conclusiones (sin teléfonos ni contactos de terceros)
const L = [];
if (/^ESCALADO/.test(estadoManager)) L.push('Escalado a Logística: ' + estadoManager.replace(/^ESCALADO A LOGISTICA - /, '') + '.');
if (w1) L.push('Biblioteca: ' + w1.modelo + ', bulto más pesado ' + (w1.peso_bulto_mas_pesado_kg ?? 'sin dato') + ' kg, bultos ' + (w1.cantidad_bultos ?? 'sin dato') + '.');
if (w2) L.push(w2.necesita_tercero ? 'Hace falta tercero (motivo: ' + (w2.motivo || 'sin dato') + ').' : 'No haría falta tercero. Vehículos propios capaces: ' + (w2.vehiculos_capaces || []).join(', ') + '; libres ese día: ' + ((w2.vehiculos_capaces_libres || []).join(', ') || 'ninguno') + '.');
if (w3 && w3.total_encontrados) L.push('Terceros encontrados en la zona: ' + w3.total_encontrados.gruas + ' grúas y ' + w3.total_encontrados.autoelevadores + ' autoelevadores (el detalle está en el log del Manager).');
if (!L.length) L.push('El Manager no devolvió datos para este caso (' + (estadoManager || 'sin estado') + ').');
const resultado = L.join('\n').slice(0, 1500);

// Estado del caso: faltan datos bloqueantes -> Datos incompletos; si no, según lo que dijo el Manager
let estado;
if (m4.faltantes_bloqueantes > 0 || /^ESCALADO/.test(estadoManager)) estado = 'Datos incompletos';
else if (/TERCEROS SUGERIDOS/.test(estadoManager) || (w2 && w2.necesita_tercero)) estado = 'Esperando terceros';
else estado = 'en revision';

// Borrador de respuesta al cliente: plantilla fija, básica, sin precios ni datos internos; termina en "Atte"
const nombre = String(m4.contacto_nombre || '').trim().split(/\s+/)[0] || '';
const equipoTxt = [c['Equipo'], c['Modelo']].filter(Boolean).join(' ');
const dest = c['Destino'] ? ' con destino a ' + String(c['Destino']).slice(0, 120) : '';
const B = [];
B.push('Buen día' + (nombre ? ' ' + nombre : '') + ',');
B.push('');
B.push('Recibimos tu pedido de presupuesto' + (equipoTxt ? ' para el traslado de ' + equipoTxt : '') + dest + '.');
B.push('');
if (m4.faltantes.length) {
  B.push('Para poder armarlo necesitamos que nos confirmes lo siguiente:');
  m4.faltantes.forEach(f => B.push('- ' + f));
  B.push('');
  B.push('En cuanto lo tengamos, te enviamos el presupuesto.');
} else {
  B.push('Estamos revisando los datos y en breve te enviamos el presupuesto.');
}
B.push('');
B.push('Atte');
const borrador = B.join('\n');
const asuntoBase = m4.asunto_normalizado || ('Presupuesto - ' + (equipoTxt || 'solicitud') + (c['Destino'] ? ' - ' + String(c['Destino']).slice(0, 60) : ''));
const borradorAsunto = m4.canal === 'Mail' ? 'Re: ' + asuntoBase : asuntoBase;

// Aviso de Slack (sin teléfonos, mails ni contenido del correo)
const link = 'https://airtable.com/appajVJZjYzNw3vOE/tblgoqkyNZ6CEdnPf/' + m4.caso_id;
const S = [];
S.push(':inbox_tray: *Nueva solicitud - Nº de Presupuesto ' + m4.nro_presupuesto + '*' + (m4.existe_caso ? ' (se actualizó un caso ya abierto)' : ''));
S.push('*Canal de entrada:* ' + m4.canal);
S.push('*Empresa:* ' + (m4.empresa || 'sin dato') + '  |  *Equipo:* ' + (equipoTxt || 'sin dato') + '  |  *Destino:* ' + (c['Destino'] || 'sin dato'));
S.push('*Estado del caso:* ' + estado);
S.push('*Datos que faltan:* ' + (m4.faltantes.length ? m4.faltantes.join('; ') : 'ninguno'));
S.push('*Resultado del Manager:* ' + resultado.replace(/\n/g, ' '));
let adjuntaFotos = false;
try { adjuntaFotos = $('Unir caso').first().json.menciona_fotos === true; } catch (e) { adjuntaFotos = false; }
if (adjuntaFotos) S.push(':paperclip: El cliente indicó que adjunta fotos o video del camino: revisarlos en el mail original.');
if (m4.varios_pedidos) S.push(':warning: El correo parece traer ' + m4.cantidad_pedidos + ' pedidos. Se procesó solo el primero: cargá los demás con el formulario.');
if (m4.correos_omitidos.length) S.push(':warning: Llegaron ' + m4.correos_omitidos.length + ' correos más juntos y NO se procesaron (asuntos: ' + m4.correos_omitidos.join(' | ') + '). Reenviarlos de a uno.');
S.push('El borrador de respuesta quedó en Borradores de Gmail del agente. Nada se envió al cliente.');
S.push('Caso en Airtable: ' + link);

return [{ json: {
  caso_id: m4.caso_id, nro_presupuesto: m4.nro_presupuesto, estado_caso: estado, resultado_manager: resultado,
  datos_que_faltan: c['Datos que faltan'] || '',
  borrador_asunto: borradorAsunto.slice(0, 200), borrador_texto: borrador, borrador_para: m4.contacto_email || '',
  slack_texto: S.join('\n').slice(0, 3500)
} }];
